// Validate and extract intake form fields
const body = $input.first().json.body || $input.first().json;

const required = ['use_case_title', 'business_unit', 'problem_statement', 'data_sources', 'expected_outcome'];
const missing = required.filter(field => !body[field]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Build structured intake object
const intake = {
  id: `INTAKE-${Date.now()}`,
  timestamp: new Date().toISOString(),
  submitter_email: body.submitter_email || 'unknown@company.com',
  use_case_title: body.use_case_title,
  business_unit: body.business_unit,
  problem_statement: body.problem_statement,
  current_process: body.current_process || 'Not provided',
  data_sources: body.data_sources,
  data_sensitivity: body.data_sensitivity || 'unknown',
  expected_outcome: body.expected_outcome,
  estimated_users: body.estimated_users || 'unknown',
  estimated_roi: body.estimated_roi || 'Not provided',
  external_vendor: body.external_vendor || false,
  regulatory_domain: body.regulatory_domain || 'none'
};

return [{ json: intake }];

