// Parse Claude's classification response
const claudeResponse = $input.first().json;
const intake = $('Validate & Extract Fields').first().json;

// Extract text content from Claude response
const content = claudeResponse.content[0].text;

let classification;
try {
  classification = JSON.parse(content);
} catch (e) {
  // Fallback if Claude returns non-JSON
  classification = {
    risk_tier: 'MEDIUM',
    risk_score: 5,
    primary_risk_factors: ['Classification parsing error - manual review required'],
    required_controls: ['Manual risk assessment'],
    approval_path: 'AI Governance Board',
    estimated_review_days: 5,
    classification_rationale: 'Automated classification failed. Manual review triggered.',
    recommended_next_steps: ['Contact AI Governance team for manual review']
  };
}

// Merge intake + classification
const result = {
  ...intake,
  classification: classification,
  status: 'CLASSIFIED',
  classified_at: new Date().toISOString()
};

return [{ json: result }];

// AUTO-APPROVE: LOW risk use cases
const data = $input.first().json;

return [{
  json: {
    ...data,
    approval_decision: 'AUTO_APPROVED',
    approved_by: 'AI Governance System',
    approval_timestamp: new Date().toISOString(),
    notification_sent_to: data.submitter_email,
    next_action: 'Submit to AI Platform team for build queue',
    message: `Your AI use case "${data.use_case_title}" has been automatically approved (LOW risk). It has been added to the AI Platform build queue. Expected review: ${data.classification.estimated_review_days} business days.`
  }
}];

// ROUTE TO MANAGER: MEDIUM risk use cases
const data = $input.first().json;

// Determine approver based on business unit
const approverMap = {
  'Sales': 'sales-manager@company.com',
  'HR': 'hr-manager@company.com',
  'Finance': 'finance-manager@company.com',
  'Legal': 'legal-manager@company.com',
  'Engineering': 'eng-manager@company.com',
  'Marketing': 'marketing-manager@company.com',
  'Operations': 'ops-manager@company.com'
};

const approver = approverMap[data.business_unit] || 'ai-governance@company.com';

return [{
  json: {
    ...data,
    approval_decision: 'PENDING_MANAGER_APPROVAL',
    assigned_approver: approver,
    approval_deadline: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
    notification_sent_to: [data.submitter_email, approver],
    next_action: `Awaiting manager approval from ${approver}`,
    message: `Your AI use case "${data.use_case_title}" requires manager approval (MEDIUM risk). Your manager at ${approver} has been notified. Expected decision: ${data.classification.estimated_review_days} business days.`
  }
}];

// ROUTE TO AI GOVERNANCE BOARD: HIGH risk
const data = $input.first().json;

return [{
  json: {
    ...data,
    approval_decision: 'PENDING_GOVERNANCE_BOARD',
    assigned_approver: 'ai-governance-board@company.com',
    approval_deadline: new Date(Date.now() + 10 * 24 * 60 * 60 * 1000).toISOString(),
    notification_sent_to: [data.submitter_email, 'ai-governance-board@company.com'],
    required_documentation: [
      'Data Privacy Impact Assessment',
      'Security Risk Assessment',
      'Bias & Fairness Evaluation Plan',
      'Human-in-the-loop documentation',
      'Audit trail specification'
    ],
    next_action: 'Complete required documentation and submit to AI Governance Board',
    message: `Your AI use case "${data.use_case_title}" requires AI Governance Board review (HIGH risk). Complete the required documentation within 5 business days. Board review: ${data.classification.estimated_review_days} business days.`
  }
}];

// ESCALATE: CRITICAL risk — CISO + Legal + Governance Board
const data = $input.first().json;

return [{
  json: {
    ...data,
    approval_decision: 'CRITICAL_ESCALATION',
    assigned_approver: 'CISO + Legal + AI Governance Board',
    notification_sent_to: [
      data.submitter_email,
      'ciso@company.com',
      'legal@company.com',
      'ai-governance-board@company.com',
      'cto@company.com'
    ],
    required_documentation: [
      'Full Data Privacy Impact Assessment (DPIA)',
      'Legal Compliance Review',
      'Security Architecture Review',
      'Executive Risk Acceptance',
      'Regulatory Compliance Documentation',
      'Incident Response Plan',
      'Model Explainability Documentation',
      'Third-party Vendor Security Assessment (if applicable)'
    ],
    hold_reason: 'Use case placed on HOLD pending CRITICAL risk review',
    next_action: 'CISO + Legal + AI Governance Board notified. Do not proceed without written approval.',
    message: `CRITICAL ALERT: AI use case "${data.use_case_title}" has been flagged as CRITICAL risk. CISO, Legal, and AI Governance Board have been notified. Use case is on HOLD. Do not proceed without written executive approval.`
  }
}];

// LOG to audit trail — all risk levels
const data = $input.first().json;

const auditEntry = {
  audit_id: `AUDIT-${Date.now()}`,
  intake_id: data.id,
  timestamp: new Date().toISOString(),
  use_case_title: data.use_case_title,
  business_unit: data.business_unit,
  submitter: data.submitter_email,
  risk_tier: data.classification.risk_tier,
  risk_score: data.classification.risk_score,
  approval_decision: data.approval_decision,
  assigned_approver: data.assigned_approver || 'System Auto-Approved',
  primary_risk_factors: data.classification.primary_risk_factors,
  required_controls: data.classification.required_controls,
  classification_rationale: data.classification.classification_rationale,
  action_taken: `Routed to: ${data.approval_decision}`
};

console.log('AUDIT LOG:', JSON.stringify(auditEntry, null, 2));

return [{ json: { ...data, audit_entry: auditEntry } }];
